import PersonnelOrderPrintDocument from "@/app/directory/personnel/_components/print/PersonnelOrderPrintDocument";
import type { PersonnelOrderPrintViewModel } from "@/app/directory/personnel/_lib/personnelOrderPrintViewModel";
import type { PersonnelOrderTemplatePreview } from "../_lib/personnelOrderTemplatesApi.client";

/** Adapt rendered template text to the same document used for transfer orders.
 * No order is created and no text is regenerated by the print model.
 */
export default function QualificationCategoryOrderDocument({ locale, previews }: {
  locale: "ru" | "kk";
  previews: Record<"ru" | "kk", PersonnelOrderTemplatePreview>;
}) {
  const localized = (key: "title" | "preamble" | "body" | "basis") => ({ru: previews.ru[key], kk: previews.kk[key]});
  const model: PersonnelOrderPrintViewModel = {
    orderId: 0, orderNumber: null, orderDate: null, status: "DRAFT", statusMark: "draft",
    organization: {}, placeOfIssue: {}, documentTypeCode: "QUALIFICATION_CATEGORY",
    title: localized("title"), preamble: localized("preamble"), closing: null,
    items: [{
      itemId: 0, itemNumber: 1, itemTypeCode: "QUALIFICATION_CATEGORY", employeeId: null,
      employeeName: null, effectiveDate: null, body: localized("body"), basis: null,
      context: {
        itemNumber: 1, itemTypeCode: "QUALIFICATION_CATEGORY", employeeName: null, effectiveDate: null,
        orgUnitName: null, positionName: null, toOrgUnitName: null, toPositionName: null,
        rate: null, toRate: null, concurrentRate: null, remainingRate: null, totalRate: null,
        terminationReason: null, payload: {},
      },
    }],
    basis: [localized("basis")],
    signatory: {
      position: {ru: "[Должность руководителя]", kk: "[Басшының лауазымы]"},
      fio: locale === "ru" ? "[Фамилия И.]" : "[Тегі А.]",
    },
    acknowledgements: [],
    executorName: locale === "ru" ? "[Инициалы и фамилия исполнителя]" : "[Орындаушының аты-жөні]",
  };
  return <section lang={locale} className="min-w-0 rounded-lg border border-zinc-200 bg-white p-5 text-black" data-testid={`category-order-document-${locale}`}>
    <p className="mb-4 text-sm font-semibold">{locale === "ru" ? "RU · Русский" : "KK · Қазақша"}</p>
    <PersonnelOrderPrintDocument model={model} language={locale} />
  </section>;
}
